import { defineSchema, s } from "convex/schema";

export default defineSchema({
  webhooks: s.table({
    payload: s.string(),
    runId: s.string(),
  }),
});

import { query, internalMutation } from "./_generated/server";
import { v } from "convex/values";

// Internal mutation used by the HTTP action to insert a webhook record.
// Internal mutations are not exposed publicly but can be called via
// ctx.runMutation from HTTP actions.
export const insertWebhook = internalMutation({
  args: {
    payload: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    await ctx.db.insert("webhooks", {
      payload: args.payload,
      runId: args.runId,
    });
  },
});

// Public query: returns all webhook records matching the given runId.
export const get_webhook = query({
  args: {
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    return await ctx.db
      .query("webhooks")
      .filter((q) => q.eq(q.field("runId"), args.runId))
      .collect();
  },
});

import { httpRouter, httpAction } from "./_generated/server";
import { internal } from "./_generated/api";

const http = httpRouter();

// POST /webhook
// Reads a JSON body containing `payload` (string) and `runId` (string),
// then inserts a new record into the `webhooks` table via an internal mutation.
http.route({
  path: "/webhook",
  method: "POST",
  handler: httpAction(async (ctx, request) => {
    let body: any;
    try {
      body = await request.json();
    } catch (err) {
      return new Response(
        JSON.stringify({ error: "Invalid JSON body" }),
        { status: 400, headers: { "Content-Type": "application/json" } },
      );
    }

    const payload = body?.payload;
    const runId = body?.runId;

    if (typeof payload !== "string" || typeof runId !== "string") {
      return new Response(
        JSON.stringify({
          error: "Missing or invalid `payload` or `runId` (must be strings)",
        }),
        { status: 400, headers: { "Content-Type": "application/json" } },
      );
    }

    await ctx.runMutation(internal.webhooks.insertWebhook, {
      payload,
      runId,
    });

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  }),
});

export default http;

